class Solution {
public:
    int findPermutationDifference(string s, string t) {
        vector<int> pos_s(26);
        for (int i = 0; i < s.size(); ++i) pos_s[s[i] - 'a'] = i;
        int ans = 0;
        for (int i = 0; i < t.size(); ++i) {
            ans += abs(pos_s[t[i] - 'a'] - i);
        }
        return ans;
    }
};

class Solution {
    public int findPermutationDifference(String s, String t) {
        int[] posS = new int[26];
        for (int i = 0; i < s.length(); i++) posS[s.charAt(i) - 'a'] = i;
        int ans = 0;
        for (int i = 0; i < t.length(); i++) {
            ans += Math.abs(posS[t.charAt(i) - 'a'] - i);
        }
        return ans;
    }
}

var findPermutationDifference = function(s, t) {
    const posS = new Array(26);
    for (let i = 0; i < s.length; i++) posS[s.charCodeAt(i) - 97] = i;
    let ans = 0;
    for (let i = 0; i < t.length; i++) {
        ans += Math.abs(posS[t.charCodeAt(i) - 97] - i);
    }
    return ans;
};
